sys_security_acl.script:
(function() {
    var currentUser = gs.getUserID();

    var scheduleDate = current.schedule_date;

    var scheduleGR = new GlideRecord('x_1567520_shark_0_schedule');
    if (scheduleGR.get(scheduleDate)) {
        if (scheduleGR.instructor == currentUser) {
            return true; 
        }
    }

    return false;
})();
